/* prog19_palindrome_checker – reproduced behaviour
 *
 * The program checks whether its first command‑line argument is a palindrome.
 * It ignores case and all non‑alphanumeric characters.
 * If the raw argument is longer than 1024 characters it prints "TOO_LONG".
 * With no argument it treats the empty string as a palindrome.
 *
 * Output (via puts):
 *   PALINDROME
 *   NOT_PALINDROME
 *   TOO_LONG
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_RAW_LEN 1024

/* Normalise a string:
 *   - keep only letters and digits,
 *   - convert letters to lower case.
 * The result is stored in a newly allocated buffer that the caller must free.
 */
static char *normalise(const char *src)
{
    size_t len = strlen(src);
    char *buf = malloc(len + 1);          /* at most the same length */
    if (!buf) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    size_t pos = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char ch = (unsigned char)src[i];
        if (isalpha(ch)) {
            buf[pos++] = (char)tolower(ch);
        } else if (isdigit(ch)) {
            buf[pos++] = (char)ch;
        }
        /* all other characters are ignored */
    }
    buf[pos] = '\0';
    return buf;
}

/* Return 1 if the string is a palindrome, 0 otherwise. */
static int is_palindrome(const char *s)
{
    size_t i = 0;
    size_t j = strlen(s);
    if (j == 0) return 1;          /* empty string is a palindrome */
    j--;                           /* index of last character */

    while (i < j) {
        if (s[i] != s[j])
            return 0;
        ++i;
        --j;
    }
    return 1;
}

int main(int argc, char *argv[])
{
    /* No argument → empty string → palindrome */
    if (argc <= 1) {
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t raw_len = strlen(input);

    if (raw_len > MAX_RAW_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    char *norm = normalise(input);
    int ok = is_palindrome(norm);
    free(norm);

    puts(ok ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
